INSERT INTO regular_expressions (name, pattern, description, regex101_id) VALUES ('Discovery+', '\b(DSCP)\b', 'Discovery+ (pronounced "Discovery Plus"; stylized as discovery+) is an American multinational subscription video on-demand over-the-top streaming service owned by Warner Bros. Discovery (WBD).[1] The service focuses on factual programming drawn from the libraries of Discovery''s main channel brands, as well as original series (including spin-offs of programs from Discovery''s television networks), and content from A&E Networks, NBCUniversal, and Discovery+''s corporate sibling CNN.', NULL);
INSERT INTO regular_expression_tags (regular_expression_name, tag_name) VALUES ('Discovery+', 'Streaming Service');
INSERT INTO regular_expression_tags (regular_expression_name, tag_name) VALUES ('Discovery+', 'WEB-DL');
INSERT INTO custom_format_conditions (custom_format_name, name, type, arr_type, negate, required) VALUES ('DSCP', 'DSCP Regex', 'release_title', 'all', 0, 1);
INSERT INTO condition_patterns (custom_format_name, condition_name, regular_expression_name) VALUES ('DSCP', 'DSCP Regex', 'Discovery+');
INSERT INTO custom_formats (name, description, include_in_rename) VALUES ('HBO', 'Matches ''HBO'' WEB-DLs', 1);
