INSERT INTO condition_sources (custom_format_name, condition_name, source) VALUES ('HBO', 'WEB-DL', 'web_dl');
INSERT INTO custom_format_conditions (custom_format_name, name, type, arr_type, negate, required) VALUES ('HBO', 'WEBRip', 'source', 'sonarr', 0, 0);
INSERT INTO condition_sources (custom_format_name, condition_name, source) VALUES ('HBO', 'WEBRip', 'webrip');
INSERT INTO regular_expressions (name, pattern, description, regex101_id) VALUES ('HBO', '\b(HBO)(?=[\W_]+WEB[ ._-]?(DL|RIP)\b)', 'Home Box Office (HBO) is an American premium television network and service, which is the flagship property of namesake parent Home Box Office, Inc., a subsidiary of Warner Bros. Discovery. The overall Home Box Office business unit is based at Warner Bros. Discovery''s corporate headquarters inside 30 Hudson Yards in Manhattan. Programming featured on the service consists primarily of theatrically released motion pictures and original television programs as well as made-for-cable movies, documentaries, occasional comedy, and concert specials, and periodic interstitial programs (consisting of short films and making-of documentaries).', NULL);
INSERT INTO regular_expression_tags (regular_expression_name, tag_name) VALUES ('HBO', 'Streaming Service');
INSERT INTO regular_expression_tags (regular_expression_name, tag_name) VALUES ('HBO', 'WEB-DL');
